import{_ as e,H as t,f as o,i as r}from"./chunks/framework.Cvt1eIE0.js";const u=JSON.parse('{"title":"第三章：API Key 获取与配置","description":"获取 Anthropic 官方的 API Key 并配置到 Claude Code","frontmatter":{"title":"第三章：API Key 获取与配置","description":"获取 Anthropic 官方的 API Key 并配置到 Claude Code"},"headers":[],"relativePath":"guide/1-getting-started/3-api-key-setup.md","filePath":"guide/1-getting-started/3-api-key-setup.md"}'),i={name:"guide/1-getting-started/3-api-key-setup.md"};function l(s,a,n,h,d,c){return t(),o("div",null,[...a[0]||(a[0]=[r(`<h1 id="第三章-api-key-获取与配置" tabindex="-1">第三章：API Key 获取与配置 <a class="header-anchor" href="#第三章-api-key-获取与配置" aria-label="Permalink to &quot;第三章：API Key 获取与配置&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">学习目标</p><p>学完这章，你能拿到 Anthropic 官方的 API Key，并配置到 Claude Code。</p></div><h2 id="什么是-api-key" tabindex="-1">什么是 API Key？ <a class="header-anchor" href="#什么是-api-key" aria-label="Permalink to &quot;什么是 API Key？&quot;">​</a></h2><p>API Key 就像一把钥匙，允许你的电脑连接到 Claude 的服务。</p><ul><li>没有 Key = 无法使用 Claude Code</li><li>有 Key = 可以无限使用（按用量付费）</li></ul><h2 id="注册-anthropic-账号" tabindex="-1">注册 Anthropic 账号 <a class="header-anchor" href="#注册-anthropic-账号" aria-label="Permalink to &quot;注册 Anthropic 账号&quot;">​</a></h2><h3 id="_1-打开官网" tabindex="-1">1. 打开官网 <a class="header-anchor" href="#_1-打开官网" aria-label="Permalink to &quot;1. 打开官网&quot;">​</a></h3><p>在浏览器里打开 <a href="https://anthropic.com" target="_blank" rel="noreferrer">anthropic.com</a></p><h3 id="_2-注册账号" tabindex="-1">2. 注册账号 <a class="header-anchor" href="#_2-注册账号" aria-label="Permalink to &quot;2. 注册账号&quot;">​</a></h3><p>点击 &quot;Sign Up&quot;，可以用 Google 账号直接登录。</p><h3 id="_3-登录-console" tabindex="-1">3. 登录 Console <a class="header-anchor" href="#_3-登录-console" aria-label="Permalink to &quot;3. 登录 Console&quot;">​</a></h3><p>注册完成后，打开 <a href="https://console.anthropic.com" target="_blank" rel="noreferrer">console.anthropic.com</a>，用你的账号登录。</p><h2 id="创建-api-key" tabindex="-1">创建 API Key <a class="header-anchor" href="#创建-api-key" aria-label="Permalink to &quot;创建 API Key&quot;">​</a></h2><h3 id="_1-进入-api-keys-页面" tabindex="-1">1. 进入 API Keys 页面 <a class="header-anchor" href="#_1-进入-api-keys-页面" aria-label="Permalink to &quot;1. 进入 API Keys 页面&quot;">​</a></h3><p>登录后，在左侧菜单找到 &quot;API Keys&quot;，点击进入。</p><h3 id="_2-创建新-key" tabindex="-1">2. 创建新 Key <a class="header-anchor" href="#_2-创建新-key" aria-label="Permalink to &quot;2. 创建新 Key&quot;">​</a></h3><p>点击 &quot;Create Key&quot; 按钮。</p><h3 id="_3-复制-key" tabindex="-1">3. 复制 Key <a class="header-anchor" href="#_3-复制-key" aria-label="Permalink to &quot;3. 复制 Key&quot;">​</a></h3><p><strong>重要</strong>：Key 只显示一次！复制后妥善保存。</p><h2 id="配置-claude-code" tabindex="-1">配置 Claude Code <a class="header-anchor" href="#配置-claude-code" aria-label="Permalink to &quot;配置 Claude Code&quot;">​</a></h2><h3 id="_1-打开终端" tabindex="-1">1. 打开终端 <a class="header-anchor" href="#_1-打开终端" aria-label="Permalink to &quot;1. 打开终端&quot;">​</a></h3><h3 id="_2-运行-claude-code" tabindex="-1">2. 运行 Claude Code <a class="header-anchor" href="#_2-运行-claude-code" aria-label="Permalink to &quot;2. 运行 Claude Code&quot;">​</a></h3><p>输入：</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">claude</span></span></code></pre></div><p>Claude Code 会提示你输入 API Key。粘贴刚才复制的 Key，回车。</p><h3 id="_3-验证成功" tabindex="-1">3. 验证成功 <a class="header-anchor" href="#_3-验证成功" aria-label="Permalink to &quot;3. 验证成功&quot;">​</a></h3><p>看到类似下面的消息就说明配置成功了：</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>✓ API Key configured successfully</span></span>
<span class="line"><span>You can now start chatting!</span></span></code></pre></div><h2 id="安全注意事项" tabindex="-1">安全注意事项 <a class="header-anchor" href="#安全注意事项" aria-label="Permalink to &quot;安全注意事项&quot;">​</a></h2><div class="warning custom-block"><p class="custom-block-title">非常重要</p><p>API Key = 你的银行卡密码</p></div><ul><li><strong>不要分享</strong>：不要把 Key 发给任何人</li><li><strong>不要提交到 GitHub</strong>：在 <code>.gitignore</code> 里排除包含 Key 的文件</li><li><strong>如果泄露了</strong>：立刻到官网删除那个 Key，重新生成一个新的</li></ul><h2 id="前置知识" tabindex="-1">前置知识 <a class="header-anchor" href="#前置知识" aria-label="Permalink to &quot;前置知识&quot;">​</a></h2><p>会注册网站账号。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>Q: API Key 要钱吗？</strong></p><p>A: 有免费额度，新用户可以用很久。后期如果用量大才需要付费。</p><p><strong>Q: Key 泄露了怎么办？</strong></p><p>A: 立刻到 <a href="https://console.anthropic.com" target="_blank" rel="noreferrer">console.anthropic.com</a> 删除那个 Key，重新生成一个。</p><p><strong>Q: 看不到 Create Key 按钮？</strong></p><p>A: 可能账号没激活，检查邮箱有没有收到验证邮件。</p><h2 id="练习题" tabindex="-1">练习题 <a class="header-anchor" href="#练习题" aria-label="Permalink to &quot;练习题&quot;">​</a></h2><p>成功在 Claude Code 里问&quot;你好&quot;，并收到回复。</p><h2 id="下一章" tabindex="-1">下一章 <a class="header-anchor" href="#下一章" aria-label="Permalink to &quot;下一章&quot;">​</a></h2><p>配置好之后，下一章我们会进行第一次真正的对话！</p><p><a href="/guide/1-getting-started/4-first-conversation.html">👉 第四章：首次对话</a></p>`,45)])])}const b=e(i,[["render",l]]);export{u as __pageData,b as default};
